PREPARE p9_vector_query (VECTOR(64), STRING, STRING, INT8) AS
SELECT vector_id, encode(event_hash,'hex') AS event_hash,
       encode(vector_digest,'hex') AS vector_digest,
       vector <-> $1 AS distance
FROM ck.context_vectors
WHERE task_id = $2 AND namespace = $3
ORDER BY vector <-> $1
LIMIT $4;
EXECUTE p9_vector_query('[0.000000,0.000000,0.000000,0.000000,0.000000,0.273674,0.000000,0.000000,0.000000,0.000000,0.000000,0.272675,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.453460,0.000000,0.000000,0.000000,0.000000,0.413508,0.000000,0.000000,0.000000,0.000000,0.000000,0.331605,0.000000,-0.344590,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.495410,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000]'::VECTOR(64),'ck-p9-live-refuse-r1','ck-p9-completion',8);
DEALLOCATE p9_vector_query;
